"use client";

import { useMemo } from "react";
import { api } from "./index";
import { useQuery } from "./useQuery";
import type { BrResult, Match, Side } from "../matches";

export type { BrResult, Match, MatchStatus, Side } from "../matches";

/** What the organiser sends to create or change matches. Missing ids are generated by the server. */
export type MatchInput = Partial<Omit<Match, "updatedAt">>;
/** A result for one match. The winner is worked out from the scores unless it is a forfeit. */
export interface ResultInput { scoreA: number; scoreB: number; status?: "finished" | "forfeit"; winner?: Side }
export interface MatchesState { matches: Match[]; br: BrResult[] }

const base = (eventId: string) => `/events/${encodeURIComponent(eventId)}`;
const path = (eventId: string) => `${base(eventId)}/matches`;
const arr = (x: unknown): BrResult[] => (Array.isArray(x) ? (x as BrResult[]) : []);

/** The matches of one event (owner, editor and viewer can read; owner and editor can change). Written against docs/usp2-contract.md. */
export const matches = {
  list: (eventId: string, opt: { ttl?: number; force?: boolean } = {}) => api.get<MatchesState>(path(eventId), { ttl: opt.ttl ?? 5000, swr: 0, force: opt.force }).then((r) => ({ matches: r?.matches ?? [], br: arr(r?.br) })),
  /** Creates or updates matches by id and returns the full list. `replaceStage` deletes that stage first. */
  put: (eventId: string, body: { matches: MatchInput[]; replaceStage?: string }) => api.put<{ matches: Match[] }>(path(eventId), body),
  /** Records a result. Returns the match and every match the result changed (the winner moving on, results undone). */
  result: (eventId: string, matchId: string, input: ResultInput) => api.post<{ match: Match; changed: Match[] }>(`${path(eventId)}/${encodeURIComponent(matchId)}/result`, input),
  /** Deletes every match of one stage, or of the whole event when no stage is given. */
  clear: (eventId: string, stage?: string) => api.del<unknown>(stage === undefined ? path(eventId) : `${path(eventId)}?stage=${encodeURIComponent(stage)}`),
  brList: (eventId: string) => api.get<unknown>(`${base(eventId)}/br-results`, { ttl: 0, swr: 0 }).then((r) => arr(Array.isArray(r) ? r : (r as { results?: unknown; br?: unknown })?.results ?? (r as { br?: unknown })?.br)),
  brPut: (eventId: string, body: { results: BrResult[]; replace?: boolean }) => api.put<unknown>(`${base(eventId)}/br-results`, body),
};

/** The matches of an event, refreshed every 15 seconds while the tab is visible (slower while nothing changes) and cached between screens. */
export function useMatches(eventId: string | null) {
  const q = useQuery<MatchesState>(eventId ? path(eventId) : null, { pollMs: 15_000, maxPollMs: 90_000, ttl: 5000 });
  const data = useMemo(() => (q.data ? { matches: q.data.matches ?? [], br: arr(q.data.br) } : undefined), [q.data]);
  return { matches: data?.matches ?? [], br: data?.br ?? [], loaded: !!data, loading: q.loading, error: q.error, refetch: q.refetch };
}
